import{_ as d,o as t,c as i,a5 as e}from"./chunks/framework.a5no_H3L.js";const l="/unity/06-advanced-chapter-01-player-settings.png",o=JSON.parse('{"title":"跨平台打包与发布","description":"你的游戏只在编辑器里跑，还没变成玩家能下载运行的程序。读完这一篇，你能把项目打包成 Windows 或 macOS 的可执行程序，并理解打包前要检查什么。","frontmatter":{"type":"howto","level":"intermediate"},"headers":[],"relativePath":"unity/06-advanced/chapter-01-build-publish.md","filePath":"unity/06-advanced/chapter-01-build-publish.md"}'),r={name:"unity/06-advanced/chapter-01-build-publish.md"};function n(c,a,s,u,h,p){return t(),i("div",null,[...a[0]||(a[0]=[e('<h1 id="跨平台打包与发布" tabindex="-1" data-src-line="2" data-src-file="unity/06-advanced/chapter-01-build-publish.md">跨平台打包与发布 <a class="header-anchor" href="#跨平台打包与发布" aria-label="Permalink to &quot;跨平台打包与发布&quot;">​</a></h1><p data-src-line="4" data-src-file="unity/06-advanced/chapter-01-build-publish.md">你的游戏只在编辑器里跑，还没变成玩家能下载运行的程序。读完这一篇，你能把项目打包成 Windows 或 macOS 的可执行程序，并理解打包前要检查什么。</p><h2 id="_1-打包前的准备" tabindex="-1" data-src-line="6" data-src-file="unity/06-advanced/chapter-01-build-publish.md">1. 打包前的准备 <a class="header-anchor" href="#_1-打包前的准备" aria-label="Permalink to &quot;1. 打包前的准备&quot;">​</a></h2><p data-src-line="8" data-src-file="unity/06-advanced/chapter-01-build-publish.md">打包是把你的场景和资源编译成目标平台能运行的程序。动手前检查三件事：</p><ol data-src-line="10" data-src-file="unity/06-advanced/chapter-01-build-publish.md"><li data-src-line="10" data-src-file="unity/06-advanced/chapter-01-build-publish.md"><p data-src-line="10" data-src-file="unity/06-advanced/chapter-01-build-publish.md"><strong>装好目标平台的模块</strong>。打包到 Windows 需要 Windows Build Support 模块，macOS 需要 macOS Build Support。如果之前装编辑器时没勾，现在去 Unity Hub → Installs → 对应版本 → Add modules 补装。</p></li><li data-src-line="12" data-src-file="unity/06-advanced/chapter-01-build-publish.md"><p data-src-line="12" data-src-file="unity/06-advanced/chapter-01-build-publish.md"><strong>确认场景在 Build Settings 里</strong>。打包只包含你添加进去的场景。菜单 <strong>File → Build Settings</strong>，把要打包的场景拖进 <strong>Scenes In Build</strong> 列表，第一个场景是启动场景。</p></li><li data-src-line="14" data-src-file="unity/06-advanced/chapter-01-build-publish.md"><p data-src-line="14" data-src-file="unity/06-advanced/chapter-01-build-publish.md"><strong>检查 Player Settings</strong>。Build Settings 左下角 <strong>Player Settings</strong> 打开项目设置，设置游戏名、公司名、图标、默认分辨率等。</p></li></ol><p data-src-line="16" data-src-file="unity/06-advanced/chapter-01-build-publish.md"><img src="'+l+'" alt="Player Settings：设置 Company Name、Product Name、图标等项目信息"></p><p data-src-line="18" data-src-file="unity/06-advanced/chapter-01-build-publish.md"><em>图源：<a href="https://docs.unity3d.com/6000.3/Documentation/Manual/PlayerSettings.html" target="_blank" rel="noreferrer">Unity 官方文档</a></em></p><h2 id="_2-执行打包" tabindex="-1" data-src-line="20" data-src-file="unity/06-advanced/chapter-01-build-publish.md">2. 执行打包 <a class="header-anchor" href="#_2-执行打包" aria-label="Permalink to &quot;2. 执行打包&quot;">​</a></h2><ol data-src-line="22" data-src-file="unity/06-advanced/chapter-01-build-publish.md"><li data-src-line="22" data-src-file="unity/06-advanced/chapter-01-build-publish.md">菜单 <strong>File → Build Settings</strong>。</li><li data-src-line="23" data-src-file="unity/06-advanced/chapter-01-build-publish.md">在 <strong>Platform</strong> 列表选择目标平台（Windows、macOS、Linux 等），点 <strong>Switch Platform</strong>（首次切换需要较长时间）。</li><li data-src-line="24" data-src-file="unity/06-advanced/chapter-01-build-publish.md">点 <strong>Build</strong>，选择一个输出目录。</li><li data-src-line="25" data-src-file="unity/06-advanced/chapter-01-build-publish.md">等构建完成。</li></ol><p data-src-line="27" data-src-file="unity/06-advanced/chapter-01-build-publish.md">构建产物是目标平台的可运行程序：</p><ul data-src-line="29" data-src-file="unity/06-advanced/chapter-01-build-publish.md"><li data-src-line="29" data-src-file="unity/06-advanced/chapter-01-build-publish.md">Windows：一个 <code>.exe</code> 加一个同名的 <code>_Data</code> 文件夹（两个都要给玩家）。</li><li data-src-line="30" data-src-file="unity/06-advanced/chapter-01-build-publish.md">macOS：一个 <code>.app</code> 包。</li><li data-src-line="31" data-src-file="unity/06-advanced/chapter-01-build-publish.md">WebGL：一组网页文件，需要托管到服务器才能运行。</li></ul><p data-src-line="33" data-src-file="unity/06-advanced/chapter-01-build-publish.md"><strong>成功标志</strong>：构建结束提示 Build succeeded，输出目录里出现对应平台的可执行文件，双击能运行。</p><h2 id="_3-构建失败怎么办" tabindex="-1" data-src-line="35" data-src-file="unity/06-advanced/chapter-01-build-publish.md">3. 构建失败怎么办 <a class="header-anchor" href="#_3-构建失败怎么办" aria-label="Permalink to &quot;3. 构建失败怎么办&quot;">​</a></h2><table tabindex="0"><thead data-src-line="37" data-src-file="unity/06-advanced/chapter-01-build-publish.md"><tr data-src-line="37" data-src-file="unity/06-advanced/chapter-01-build-publish.md"><th>现象</th><th>原因与处理</th></tr></thead><tbody data-src-line="39" data-src-file="unity/06-advanced/chapter-01-build-publish.md"><tr data-src-line="39" data-src-file="unity/06-advanced/chapter-01-build-publish.md"><td>Build Settings 里平台是灰的</td><td>没装该平台的 Build Support 模块，去 Hub 补装</td></tr><tr data-src-line="40" data-src-file="unity/06-advanced/chapter-01-build-publish.md"><td>构建到一半报错</td><td>看 Console 的具体错误。常见是脚本有编译错误（先修脚本）、或资源缺失</td></tr><tr data-src-line="41" data-src-file="unity/06-advanced/chapter-01-build-publish.md"><td>运行后黑屏</td><td>启动场景没设置，或场景列表是空的，把场景加进 Scenes In Build</td></tr><tr data-src-line="42" data-src-file="unity/06-advanced/chapter-01-build-publish.md"><td>文件很大</td><td>资源没压缩、或误打包了大量无用资源，检查资源导入设置</td></tr></tbody></table><h2 id="_4-各平台的特殊点" tabindex="-1" data-src-line="44" data-src-file="unity/06-advanced/chapter-01-build-publish.md">4. 各平台的特殊点 <a class="header-anchor" href="#_4-各平台的特殊点" aria-label="Permalink to &quot;4. 各平台的特殊点&quot;">​</a></h2><ul data-src-line="46" data-src-file="unity/06-advanced/chapter-01-build-publish.md"><li data-src-line="46" data-src-file="unity/06-advanced/chapter-01-build-publish.md"><strong>移动端（Android/iOS）</strong>：需要安装 JDK、Android SDK，iOS 还需要 macOS 和 Xcode。移动端打包远比桌面复杂，首次构建建议先桌面平台练手。</li><li data-src-line="47" data-src-file="unity/06-advanced/chapter-01-build-publish.md"><strong>WebGL</strong>：有内存限制（浏览器环境），纹理和资源要更省，构建后要放在 HTTP 服务器（直接双击打开本地文件可能不工作）。</li><li data-src-line="48" data-src-file="unity/06-advanced/chapter-01-build-publish.md"><strong>桌面平台</strong>：最省事，适合先跑通打包流程。</li></ul><h2 id="_5-一个最小打包流程" tabindex="-1" data-src-line="50" data-src-file="unity/06-advanced/chapter-01-build-publish.md">5. 一个最小打包流程 <a class="header-anchor" href="#_5-一个最小打包流程" aria-label="Permalink to &quot;5. 一个最小打包流程&quot;">​</a></h2><p data-src-line="52" data-src-file="unity/06-advanced/chapter-01-build-publish.md">按这个顺序走一遍，把第一个项目打包出来：</p><ol data-src-line="54" data-src-file="unity/06-advanced/chapter-01-build-publish.md"><li data-src-line="54" data-src-file="unity/06-advanced/chapter-01-build-publish.md">打开之前的项目，确认场景在 Scenes In Build 里（没有就 Add Open Scenes）。</li><li data-src-line="55" data-src-file="unity/06-advanced/chapter-01-build-publish.md">Build Settings 选 <strong>Windows</strong> 或 <strong>macOS</strong>，Switch Platform。</li><li data-src-line="56" data-src-file="unity/06-advanced/chapter-01-build-publish.md">Player Settings 里把 Product Name 改成你的游戏名。</li><li data-src-line="57" data-src-file="unity/06-advanced/chapter-01-build-publish.md">点 Build，选输出目录，等待完成。</li><li data-src-line="58" data-src-file="unity/06-advanced/chapter-01-build-publish.md">到输出目录双击运行，验证游戏能独立于编辑器运行。</li></ol><p data-src-line="60" data-src-file="unity/06-advanced/chapter-01-build-publish.md">走通这个流程，你就完成了&quot;从写代码到产出可运行程序&quot;的完整闭环。</p><h2 id="_6-下一步" tabindex="-1" data-src-line="62" data-src-file="unity/06-advanced/chapter-01-build-publish.md">6. 下一步 <a class="header-anchor" href="#_6-下一步" aria-label="Permalink to &quot;6. 下一步&quot;">​</a></h2><p data-src-line="64" data-src-file="unity/06-advanced/chapter-01-build-publish.md">打包出来了，但如果游戏卡，还得优化性能。下一篇讲性能优化概览：<a href="./chapter-02-performance.html">性能优化概览</a>。</p>',22)])])}const m=d(r,[["render",n]]);export{o as __pageData,m as default};
